export const literatureKey='paperknow-literature';
export const readingStates=[['all','全部'],['unread','待读'],['reading','阅读中'],['read','已读']];
export const scopes={full:'已有正文',abstract:'仅摘要',metadata:'仅元数据'};
export function validatePaper(input){const text=String(input.text||'').trim(),scope=Object.hasOwn(scopes,input.scope)?input.scope:'metadata',title=String(input.title||'').trim();if(!title||title.length>300)throw Error('请填写不超过 300 字符的文献标题。');if(text.length>200000)throw Error('正文最多 200,000 字符，请按章节导入。');if(scope!=='metadata'&&!text)throw Error('请选择仅元数据，或提供对应的正文 / 摘要。');let url=String(input.url||'').trim();if(url){try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))throw Error();url=parsed.href;}catch{throw Error('来源链接仅支持有效的 HTTP / HTTPS 地址。');}}const year=String(input.year||'').trim();if(year&&!/^\d{4}$/.test(year))throw Error('年份请填写四位数字，或留空。');const doi=String(input.doi||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'');if(doi&&!/^10\.\d{4,9}\/\S+$/i.test(doi))throw Error('DOI 格式应类似 10.1234/example；当前不联网核验。');const notes=Array.isArray(input.notes)?input.notes:[];if(notes.length>100)throw Error('每篇文献最多保留 100 条笔记。');return {...input,title,authors:String(input.authors||'').slice(0,1000),year,doi,url,scope,text:scope==='metadata'?'':text,tags:[...new Set((Array.isArray(input.tags)?input.tags:String(input.tags||'').split(/[，,]/)).map(t=>String(t).trim()).filter(Boolean))].slice(0,12).map(t=>t.slice(0,40)),projectId:String(input.projectId||''),status:['unread','reading','read'].includes(input.status)?input.status:'unread',fileName:String(input.fileName||'').slice(0,300),warnings:(Array.isArray(input.warnings)?input.warnings:[]).map(String).slice(0,20),notes:notes.map(n=>{if(!n||typeof n.id!=='string'||!String(n.text||'').trim()||String(n.text).length>5000)throw Error('笔记格式无效或超过 5,000 字符。');return {id:n.id,text:String(n.text),location:String(n.location||'').slice(0,300),createdAt:String(n.createdAt||''),updatedAt:String(n.updatedAt||n.createdAt||'')};})};}
export function selectLiterature(papers,{status='all',project='all',tag='all',query='',sort='added'}={},projects=[]){const names=new Map(projects.map(p=>[p.id,p.name]));const q=query.trim().toLocaleLowerCase();return papers.filter(p=>(status==='all'||p.status===status)&&(project==='all'||(project==='none'?!p.projectId:p.projectId===project))&&(tag==='all'||p.tags.includes(tag))&&(!q||[p.title,p.authors,p.doi,names.get(p.projectId)||'',...p.tags].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>sort==='title'?a.title.localeCompare(b.title,'zh-CN'):sort==='read'?(Date.parse(b.lastReadAt)||0)-(Date.parse(a.lastReadAt)||0):(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0));}
export function mergeLiteratureBackup(existing,backup){if(backup?.format!=='paperknow-literature-backup'||backup.version!==1||!Array.isArray(backup.papers)||backup.papers.length>200)throw Error('请选择 PaperKnow 文献备份 JSON（最多 200 篇）。');const ids=new Set(existing.map(p=>p.id));const added=[];for(const raw of backup.papers){if(typeof raw.id!=='string'||!raw.id||raw.id.length>200)throw Error('备份中的文献编号无效。');const paper=validatePaper(raw);if(!ids.has(paper.id)){added.push(paper);ids.add(paper.id);}}if(existing.length+added.length>200)throw Error('文献库最多保存 200 篇，请先备份。');return {papers:[...existing,...added],added:added.length,skipped:backup.papers.length-added.length};}
export function markOpened(paper,now=new Date().toISOString()){return {...paper,lastReadAt:now};}
